+++ b/src/feature-app/components/AwsMap/map.module.scss
@@ -0,0 +1,172 @@
+@use '@smart/web-components/dist/scss/variables' as *;
+.mapsContainer {
+  width: 100%;
+  height: 245px;
+  cursor: pointer;
+  %common-style {
+    width: 32px;
+    height: 32px;
+    font-size: 16px;
+    color: white;
+    border-radius: 50%;
+    position: absolute;
+    background-color: rgba(20, 20, 19, 0.6);
+    z-index: 1;
+    align-items: center;
+    justify-content: center;
+    cursor: pointer;
+  }
+  @include breakpoint(l) {
+    height: 753px;
+  }
+  position: relative;
+  .inZoom {
+    display: none;
+    @extend%common-style;
+    @include breakpoint(l) {
+      display: flex;
+      bottom: 65px;
+      right: 20px;
+    }
+  }
+  .outZoom {
+    display: none;
+    @extend%common-style;
+    @include breakpoint(l) {
+      display: flex;
+      bottom: 25px;
+      right: 20px;
+    }
+  }
+  .moveToCenter {
+    display: none;
+    @extend%common-style;
+    @include breakpoint(l) {
+      display: flex;
+      bottom: 80px;
+      right: 20px;
+    }
+  }
+  .outZoomMobile {
+    display: flex;
+    @extend%common-style;
+    bottom: 12px;
+    right: 12px;
+    z-index: 2;
+    cursor: pointer;
+    color: white;
+    border-radius: 50%;
+    font-size: var(--spacing-300);
+    position: absolute;
+    @include breakpoint(l) {
+      display: none;
+    }
+  }
+  .markerHover {
+    cursor: pointer;
+  }
+  .searchArea {
+    position: absolute;
+    z-index: 2;
+    left: 50%;
+    translate: -50%;
+    top: 30px;
+    background-color: var(--c-inverted);
+    padding: 0 12px;
+    height: 32px;
+    cursor: pointer;
+    border-radius: 16px;
+    display: flex;
+    align-items: center;
+    box-shadow:
+      0 1px 2px rgba(60, 64, 67, 0.3),
+      0 1px 3px 1px rgba(60, 64, 67, 0.15);
+    gap: var(--spacing-100);
+    p {
+      @include text-type('P-100');
+    }
+  }
+}
+.enlargeMap {
+  height: 445px;
+}
+.enlargeMap {
+  height: 500px;
+}
+:global {
+  .maplibregl-ctrl-logo,
+  .maplibregl-ctrl-attrib {
+    display: none !important;
+  }
+  .maplibregl-ctrl-group {
+    background-color: transparent !important;
+    border: none !important;
+    box-shadow: none !important;
+    margin: 10px 20px 20px 0 !important;
+    display: flex !important;
+    flex-direction: column !important;
+    gap: 8px !important;
+    > button {
+      width: 32px !important;
+      height: 32px !important;
+      background-color: rgba(20, 20, 19, 0.6) !important;
+      border-radius: 50% !important;
+      border: none !important;
+      margin: 0 !important;
+      display: flex !important;
+      align-items: center !important;
+      justify-content: center !important;
+      color: white !important;
+      box-shadow:
+        0 1px 2px rgba(60, 64, 67, 0.3),
+        0 1px 3px 1px rgba(60, 64, 67, 0.15) !important;
+      &.maplibregl-ctrl-zoom-in {
+        .maplibregl-ctrl-icon {
+          background-image: none !important;
+          position: relative;
+          &::before {
+            content: '+';
+            font-size: 18px;
+            font-weight: 50;
+            color: #fff;
+            position: absolute;
+            top: 50%;
+            left: 50%;
+            transform: translate(-50%, -50%);
+          }
+        }
+      }
+      &.maplibregl-ctrl-zoom-out {
+        .maplibregl-ctrl-icon {
+          background-image: none !important;
+          position: relative;
+          &::before {
+            content: '-';
+            font-size: 18px;
+            font-weight: 50;
+            color: #fff;
+            position: absolute;
+            top: 45%;
+            left: 50%;
+            transform: translate(-50%, -50%);
+          }
