import {Icon} from '@smart/react-components';
import {useTranslations} from '@smart/react-utils';
import {breakpoints} from '@smart/web-components';
import throttle from 'lodash/throttle';
import maplibregl from 'maplibre-gl';
import 'maplibre-gl/dist/maplibre-gl.css';
import React, {
  useCallback,
  useEffect,
  useImperativeHandle,
  useMemo,
  useRef,
  useState,
} from 'react';
import {useLocale} from '../../hooks/use-locale';
import {useTracking} from '../../hooks/use-tracking';
import type {ITrackClickMap} from '../../hooks/use-tracking-model';
import {getMapUrl} from '../../utils/aws-credentials';
import {
  createHoverIcon,
  createNumberIcon,
  createSelectedIcon,
} from '../../utils/creat-map-icon';
import {parseFallbackLocation} from '../../utils/getCurrentLocation';
import type {AwsMapProps, Feature} from '../OutletLocator/type';
import {AppModelContext} from '../app';
import styles from './map.module.scss';
import {CollapseIcon, ExpandIcon} from './zoomIcons';

const MAP_CONFIG = {
  DEFAULT_ZOOM: 5,
  MAX_ZOOM: 15,
  PADDING: 50,
  THROTTLE_DELAY: 50,
  RESIZE_DELAY: 200,
} as const;

const LAYER_NAMES = {
  OUTLETS: `outlets`,
  OUTLET_SYMBOLS: `outlet-symbols`,
} as const;

const ICON_TYPES = {
  NORMAL: `marker`,
  HOVER: `marker-hover`,
  SELECTED: `marker-selected`,
} as const;

const useIsMobile = () => {
  const [isMobile, setIsMobile] = useState(
    () => window.innerWidth <= breakpoints.l,
  );

  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth <= breakpoints.l);
    window.addEventListener(`resize`, handleResize);
    return () => window.removeEventListener(`resize`, handleResize);
  }, []);

  return isMobile;
};

export interface AwsMapRef {
  handleSearchAreaVisible: (visible: boolean) => void;
  handleMapLoaded: (isLoaded: boolean) => void;
}

export interface HereMapRef {
  handleSearchAreaVisible: (visible: boolean) => void;
  handleMapLoaded: (isLoaded: boolean) => void;
}
const AwsMap = React.forwardRef<HereMapRef, AwsMapProps>(
  (
    {
      locations,
      isOutZoom,
      selectId,
      hover,
      location,
      changeExpenedId,
      onMarkerClick,
      onMapDrag,
      setOutZoom,
    },
    forwardedRef,
  ) => {
    const {marketId} = useLocale();
    const mapRef = useRef<HTMLDivElement | null>(null);
    const map = useRef<maplibregl.Map | null>(null);
    const hoveredFeatureIdRef = useRef<string | null>(null);
    const prevSelectIdRef = useRef<string | null>(null);
    const locationsRef = useRef(locations);
    const isMapLoadeLocations = useRef<boolean>(false);

    const [isShowSearchArea, setIsShowSearchArea] = useState<boolean>(false);
    const [track] = useTracking<ITrackClickMap>();
    const isMobile = useIsMobile();

    const outletLocatorTranslation =
      React.useContext(AppModelContext).outletLocatorTranslation || {};
    const aemTranslations =
      React.useContext(AppModelContext).outletLocatorFeatureAppUi || {};
    const {t} = useTranslations(
      outletLocatorTranslation?.LatitudeAndlLongitude,
    );

    const {latitude, longitude} = useMemo(
      () => parseFallbackLocation(t(marketId)),
      [t, marketId],
    );

    const createGeoJsonData = useCallback(() => {
      if (!locations || locations.length === 0) return null;

      const features: Feature[] = locations.map((item, index) => ({
        type: `Feature`,
        geometry: {
          type: `Point`,
          coordinates: [item.lng, item.lat],
        },
        properties: {
          id: item.bpId,
          index,
          hovered: false,
          selected: selectId ? item.bpId === selectId : false,
        },
      }));

      return {
        type: `FeatureCollection` as const,
        features,
      };
    }, [locations, selectId]);

    useEffect(() => {
      if (!mapRef.current || map.current) return;

      try {
        const newMap = new maplibregl.Map({
          container: mapRef.current,
          style: getMapUrl(),
          center: [location?.lng || longitude, location?.lat || latitude],
          zoom: MAP_CONFIG.DEFAULT_ZOOM,
        });

        newMap.scrollZoom.disable();

        if (!isMobile) {
          newMap.addControl(
            new maplibregl.NavigationControl({
              showCompass: false,
              visualizePitch: false,
            }),
            `bottom-right`,
          );
        }

        newMap.on(`error`, (e) => {
          console.error(`Map error:`, e);
        });

        map.current = newMap;

        newMap.on(`load`, () => {
          console.log(`Map load event fired`);
        });

        return () => {
          newMap.remove();
          map.current = null;
        };
      } catch (error) {
        console.error(`Map initialization failed:`, error);
        return;
      }
    }, [location?.lng, location?.lat, longitude, latitude, isMobile]);

    const centerMapOnFeature = useCallback(
      (featureId: string) => {
        if (!map.current) return;

        if (!locations) return;

        const selectedLocation = locations.find(
          (loc) => loc.bpId === featureId,
        );
        if (selectedLocation) {
          map.current.flyTo({
            center: [selectedLocation.lng, selectedLocation.lat],
            duration: 1000,
          });
        }
      },
      [locations],
    );

    const fitMapToMarkers = useCallback(() => {
      if (!map.current) return;

      if (!locations || locations.length === 0 || isMapLoadeLocations?.current)
        return;

      const bounds = new maplibregl.LngLatBounds();

      locations.forEach((item) => {
        bounds.extend([item.lng, item.lat]);
      });

      map.current.fitBounds(bounds, {
        padding: MAP_CONFIG.PADDING,
        maxZoom: MAP_CONFIG.MAX_ZOOM,
      });
    }, [locations, isMapLoadeLocations]);

    const ensureAllIcons = useCallback(() => {
      if (!map.current || !locations) return;

      const addIconSafely = (iconKey: string, iconImage: ImageData | null) => {
        if (iconImage && map.current && !map.current.hasImage(iconKey)) {
          map.current.addImage(iconKey, iconImage);
        }
      };

      locations.forEach((_, index) => {
        const number = index + 1;

        addIconSafely(
          `${ICON_TYPES.NORMAL}-${number}`,
          createNumberIcon(number),
        );
        addIconSafely(`${ICON_TYPES.HOVER}-${number}`, createHoverIcon(number));
        addIconSafely(`${ICON_TYPES.SELECTED}-${number}`, createSelectedIcon());
      });
    }, [locations]);

    const clearAllHoverStates = useCallback(() => {
      if (!map.current) return;

      const source = map.current.getSource(
        LAYER_NAMES.OUTLETS,
      ) as maplibregl.GeoJSONSource;
      if (!source?._data) return;

      const data = source._data as GeoJSON.FeatureCollection;
      if (!data?.features) return;

      const updatedFeatures = data.features.map((f: GeoJSON.Feature) => {
        if (f.properties?.hovered) {
          return {
            ...f,
            properties: {
              ...f.properties,
              hovered: false,
            },
          };
        }
        return f;
      });

      source.setData({
        type: `FeatureCollection`,
        features: updatedFeatures,
      });

      hoveredFeatureIdRef.current = null;
    }, []);

    const updateFeatureState = useCallback(
      (id: string | null, stateKey: 'hovered' | 'selected', value: boolean) => {
        if (!map.current || !id) return;

        const source = map.current.getSource(
          LAYER_NAMES.OUTLETS,
        ) as maplibregl.GeoJSONSource;
        if (!source?._data) return;

        const data = source._data as GeoJSON.FeatureCollection;
        if (!data?.features) return;

        const updatedFeatures = data.features.map((f: GeoJSON.Feature) => {
          if (f.properties?.id === id) {
            return {
              ...f,
              properties: {
                ...f.properties,
                [stateKey]: value,
              },
            };
          }
          return f;
        });

        source.setData({
          type: `FeatureCollection`,
          features: updatedFeatures,
        });
      },
      [],
    );

    const updateFeatureHoverState = useCallback(
      (id: string | null, isHovered: boolean) => {
        if (!id) return;

        if (isHovered) clearAllHoverStates();
        updateFeatureState(id, `hovered`, isHovered);
        hoveredFeatureIdRef.current = isHovered ? id : null;
      },
      [clearAllHoverStates, updateFeatureState],
    );

    const updateSelectedFeature = useCallback(
      (id: string | null) => {
        if (!map.current) return;

        const source = map.current.getSource(
          LAYER_NAMES.OUTLETS,
        ) as maplibregl.GeoJSONSource;
        if (!source?._data) return;

        const data = source._data as GeoJSON.FeatureCollection;
        if (!data?.features) return;

        const updatedFeatures = data.features.map((f: GeoJSON.Feature) => ({
          ...f,
          properties: {
            ...f.properties,
            selected: f.properties?.id === id,
          },
        }));

        source.setData({
          type: `FeatureCollection`,
          features: updatedFeatures,
        });

        if (id) centerMapOnFeature(id);
      },
      [centerMapOnFeature],
    );

    // Handle marker click
    const handleMarkerClick = useCallback(
      (featureId: string) => {
        if (onMarkerClick) {
          const currentLocations = locationsRef.current;
          const selectedLocation = currentLocations?.find(
            (loc) => loc.bpId === featureId,
          );
          if (selectedLocation) {
            onMarkerClick(selectedLocation);
            changeExpenedId?.(featureId);
            track(`click`, `select_outlet.map`, `feature`, [selectedLocation]);
          }

          updateSelectedFeature(featureId);
        }
      },
      [onMarkerClick, updateSelectedFeature],
    );

    // Set up marker symbol layer and event handlers
    const setupSymbolLayer = useCallback(() => {
      if (!map.current || !locations || locations.length === 0) return;

      if (map.current.getSource(LAYER_NAMES.OUTLETS)) return;

      ensureAllIcons();

      if (!map.current) return;

      const geoJson = createGeoJsonData();
      if (!geoJson) return;

      try {
        // Add geojson source
        map.current.addSource(LAYER_NAMES.OUTLETS, {
          type: `geojson`,
          data: {
            type: `FeatureCollection` as const,
            features: geoJson.features,
          },
        });

        // Add symbol layer
        map.current.addLayer({
          id: LAYER_NAMES.OUTLET_SYMBOLS,
          type: `symbol`,
          source: LAYER_NAMES.OUTLETS,
          layout: {
            'icon-image': [
              `case`,
              [`get`, `selected`],
              [`concat`, `marker-selected-`, [`+`, [`get`, `index`], 1]],
              [`get`, `hovered`],
              [`concat`, `marker-hover-`, [`+`, [`get`, `index`], 1]],
              [`concat`, `marker-`, [`+`, [`get`, `index`], 1]],
            ],
            'icon-size': 1,
            'icon-anchor': `center`,
            'icon-allow-overlap': true,
            'symbol-sort-key': [
              `case`,
              [`get`, `selected`],
              2,
              [`get`, `hovered`],
              1,
              0,
            ],
          },
        });

        // Add mouse events
        const handleMouseMove = throttle((e: maplibregl.MapMouseEvent) => {
          if (!map.current) return;

          const features = map.current.queryRenderedFeatures(e.point, {
            layers: [LAYER_NAMES.OUTLET_SYMBOLS],
          });

          if (features.length === 0 && hoveredFeatureIdRef.current) {
            clearAllHoverStates();
            return;
          }

          if (features.length > 0) {
            const feature = features[0];
            if (feature?.properties?.id) {
              const featureId = feature.properties.id as string;
              if (featureId !== hoveredFeatureIdRef.current) {
                updateFeatureHoverState(featureId, true);
              }
            }
          }
        }, MAP_CONFIG.THROTTLE_DELAY);

        map.current.on(`click`, LAYER_NAMES.OUTLET_SYMBOLS, (e) => {
          if (e.features && e.features.length > 0) {
            const feature = e.features[0];
            if (feature?.properties?.id) {
              const featureId = feature.properties.id as string;
              handleMarkerClick?.(featureId);
            }
          }
        });

        map.current.on(`mousemove`, handleMouseMove);

        map.current.on(`dragend`, () => handleSearchAreaVisible(true));

        if (selectId) {
          centerMapOnFeature(selectId);
        } else {
          fitMapToMarkers();
        }
      } catch (error) {
        console.error(`Error setting up symbol layer:`, error);
      }
    }, [
      locations,
      selectId,
      createGeoJsonData,
      ensureAllIcons,
      clearAllHoverStates,
      updateFeatureHoverState,
      fitMapToMarkers,
      centerMapOnFeature,
      handleMarkerClick,
    ]);

    const updateMapMarkers = useCallback(() => {
      if (!map.current) return;

      if (!locations || locations.length === 0) return;

      ensureAllIcons();

      const geoJson = createGeoJsonData();
      if (!geoJson) return;

      if (map.current && map.current.getSource(LAYER_NAMES.OUTLETS)) {
        const source = map.current.getSource(
          LAYER_NAMES.OUTLETS,
        ) as maplibregl.GeoJSONSource;
        const currentData = source._data as GeoJSON.FeatureCollection;

        let enhancedFeatures = geoJson.features;

        if (currentData?.features) {
          const hoveredState: Record<string, boolean> = {};

          currentData.features.forEach((feature: GeoJSON.Feature) => {
            if (feature.properties?.id && feature.properties.hovered) {
              hoveredState[feature.properties.id] = true;
            }
          });

          enhancedFeatures = geoJson.features.map((feature) => ({
            ...feature,
            properties: {
              ...feature.properties,
              hovered: hoveredState[feature.properties.id] || false,
              selected:
                selectId != null ? feature.properties.id === selectId : false,
            },
          }));
        }

        source.setData({
          type: `FeatureCollection`,
          features: enhancedFeatures,
        });

        if (selectId) {
          centerMapOnFeature(selectId);
        } else {
          fitMapToMarkers();
        }
      } else {
        setupSymbolLayer();
      }
    }, [
      locations,
      selectId,
      createGeoJsonData,
      ensureAllIcons,
      setupSymbolLayer,
      fitMapToMarkers,
      centerMapOnFeature,
    ]);

    useEffect(() => {
      const currentSelectId = selectId ?? null;
      if (
        currentSelectId !== prevSelectIdRef.current &&
        map.current &&
        map.current.getSource(LAYER_NAMES.OUTLETS)
      ) {
        updateSelectedFeature(currentSelectId);
        prevSelectIdRef.current = currentSelectId;
      }
    }, [selectId, updateSelectedFeature]);

    useEffect(() => {
      locationsRef.current = locations;

      if (!map.current || !locations || locations.length === 0) return;

      if (map.current.getSource(LAYER_NAMES.OUTLETS)) {
        updateMapMarkers();
      } else {
        setupSymbolLayer();
      }
    }, [locations, updateMapMarkers, setupSymbolLayer]);

    useEffect(() => {
      if (!map.current || !map.current.getSource(LAYER_NAMES.OUTLETS) || !hover)
        return;

      if (hover.type === `listHover`) {
        if (hover.bpid) {
          updateFeatureHoverState(hover.bpid, true);
        } else {
          clearAllHoverStates();
        }
      }
    }, [hover, updateFeatureHoverState, clearAllHoverStates]);

    const handleMapLoaded = (isLoaded: boolean) =>
      (isMapLoadeLocations.current = isLoaded);

    const handleSearchAreaVisible = (visible: boolean) =>
      setIsShowSearchArea(visible);

    const handleSearchAreaClick = () => {
      if (map.current && onMapDrag) {
        const center = map.current.getCenter();
        onMapDrag({
          lat: center.lat,
          lng: center.lng,
        });
        handleMapLoaded(true);
      }
    };

    useImperativeHandle(forwardedRef, () => ({
      handleSearchAreaVisible,
      handleMapLoaded,
    }));

    return (
      <div
        className={`${styles.mapsContainer} ${
          isOutZoom ? styles.enlargeMap : ``
        }`}
        ref={mapRef}
      >
        {isMobile && (
          <div
            className={styles.outZoomMobile}
            onClick={() => {
              setOutZoom?.(!isOutZoom);
              setTimeout(() => {
                if (map.current) {
                  map.current?.resize();
                }
              }, MAP_CONFIG.RESIZE_DELAY);
            }}
          >
            {isOutZoom ? <CollapseIcon /> : <ExpandIcon />}
          </div>
        )}

        {isShowSearchArea && (
          <div className={styles.searchArea} onClick={handleSearchAreaClick}>
            <Icon icon={`search`} mode={200} />
            <p>{aemTranslations?.map_search_area || `Search in this area`}</p>
          </div>
        )}
      </div>
    );
  },
);

export default React.memo(AwsMap);

