import addressFormatter from '@fragaria/address-formatter';
import {useFeatureAppEnv} from '@smart/feature-app';
import {getCountryCode} from '@smart/locale-service';
import {getBeautifiedDistance} from '@smart/platform-utils';
import type {MarketId} from '@smart/platform-utils';
import {
  Button,
  Icon,
  IconLink,
  Radio,
  Text,
  TextLink,
} from '@smart/web-components';
import React, {useEffect, useRef, useState} from 'react';
import hideOutletDetailsSvg from '../../../../static/hide-outlet-details.svg';
import showOutletDetailsSvg from '../../../../static/show-outlet-details.svg';
import type {
  OutletsInfoModel,
  Services,
} from '../../../bff/get-outlets/create-outlets-info-model';
import {type DayType} from '../../common/types';
import {useLocale} from '../../hooks/use-locale';
import {useTracking} from '../../hooks/use-tracking';
import type {
  ITrackClickMapMoreDetails,
  ITrackClickOutlet,
  ITrackConfirmOutlet,
} from '../../hooks/use-tracking-model';
import {smoothScrollToCenter} from '../../utils/smoothscrollToCenter';
import {ServiceType} from '../OutletLocator/type';
import {AppModelContext} from '../app';
import styles from '../app.module.scss';
import outletStyles from './outlet.module.scss';

interface IProps {
  outlet: OutletsInfoModel;
  selectedService: string;
  getSelectedOutletBpId: (id: string, name: string) => void;
  selected?: boolean;
  onMarkerClick?: (coords: OutletsInfoModel) => void;
  outletIndex: number;
  expendId?: string;
  changeExpenedId?: (id: string) => void;
  handleMouse?: (bpid: string, type: `mapHover` | `listHover`) => void;
  hover?: {
    bpid: string;
    type: `mapHover` | `listHover`;
  };
  redirectToNextPage: (
    event: React.MouseEvent<HTMLButtonElement, MouseEvent>,
  ) => void;
}

// eslint-disable-next-line complexity
export default function Outlet({
  outlet,
  selectedService,
  getSelectedOutletBpId,
  onMarkerClick,
  outletIndex,
  selected,
  expendId,
  changeExpenedId,
  handleMouse,
  hover,
}: IProps): JSX.Element {
  const {
    config: {getSelectedOutlets, showMap, variant},
  } = useFeatureAppEnv() as {
    config: {
      getSelectedOutlets: (item: OutletsInfoModel | undefined) => void;
      showMap: boolean;
      variant: string;
    };
  };
  const [showOutletDetails, toggleOutletDetails] = useState<Boolean>(false);
  const [showMoreButton, toggleMoreButton] = useState<Boolean>(true);
  const {marketId} = useLocale();
  const selectedItemRef = useRef<HTMLDivElement>(null);
  const [track] = useTracking<
    ITrackClickOutlet | ITrackClickMapMoreDetails | ITrackConfirmOutlet
  >();

  const hovered = hover?.bpid === outlet.bpId && hover.type === `mapHover`;
  const selectedOrHovered = selected || hovered;

  const soothCard = () => {
    if (selectedItemRef.current) {
      const container = selectedItemRef?.current.parentNode as HTMLDivElement;
      if (container) {
        smoothScrollToCenter(container, selectedItemRef?.current, 300);
      }
    }
  };

  useEffect(() => {
    if (selected && selectedItemRef.current) {
      soothCard();
    }
  }, [selected]);

  useEffect(() => {
    if (selectedItemRef.current && hovered) {
      soothCard();
    }
  }, [hover]);

  const aemTranslations =
    React.useContext(AppModelContext).outletLocatorFeatureAppUi || {};

  const dayAEMTranslationsMap: {[k in DayType]: string} = {
    MO: aemTranslations.outletlocator_result_openingHours_Monday || `Monday`,
    TU: aemTranslations.outletlocator_result_openingHours_Tuesday || `Tuesday`,
    WE:
      aemTranslations.outletlocator_result_openingHours_Wednesday ||
      `Wednesday`,
    TH:
      aemTranslations.outletlocator_result_openingHours_Thursday || `Thursday`,
    FR: aemTranslations.outletlocator_result_openingHours_Friday || `Friday`,
    SA:
      aemTranslations.outletlocator_result_openingHours_Saturday || `Saturday`,
    SU: aemTranslations.outletlocator_result_openingHours_Sunday || `Sunday`,
  };

  const variantConfig =
    React.useContext(AppModelContext).outletLocatorVariant || {};
  const servicesNames = aemTranslations.serviceNames;
  const showServicesInOutletResults =
    variantConfig.featureFlags &&
    variantConfig.featureFlags.includes(`servicesInOutletResults`);
  const hasPrimaryButtonConfigured =
    variantConfig.primaryButtonLabel && variantConfig.primaryButtonPage
      ? true
      : false;
  const hasReturnViaDoneFunctionTrue =
    variantConfig.primaryButtonLabel && variantConfig.returnViaDoneFunction
      ? true
      : false;

  const handleCheck = (event: React.ChangeEvent<HTMLInputElement>) => {
    getSelectedOutletBpId(event.target.value, event.target.id);
  };

  const handleCheckAgent = (bpId: string = ``, outletName: string = ``) => {
    getSelectedOutletBpId(bpId, outletName);
    onMarkerClick && onMarkerClick(outlet);
    track(`click`, `select_outlet.list`, `feature`, [outlet]);
  };

  const renderDefaultVariantUI = () => {
    return (
      <React.Fragment>
        <Text key={outlet.bpId} variant="label-100">
          {outlet.outlet}
        </Text>
        {renderFormattedAddress()}
      </React.Fragment>
    );
  };
  const renderDefaultVariantUIwithMaps = () => {
    return (
      <React.Fragment>
        <Text
          key={outlet.bpId}
          variant="paragraph-200"
          className={outletStyles.shoplLabel}
        >
          {outlet.outlet}
        </Text>
        {renderFormattedAddressWithMaps()}
      </React.Fragment>
    );
  };

  const renderRadioButtonsVariantUI = () => {
    return (
      <Radio
        key={outlet.outlet}
        value={outlet.bpId}
        name={`outlet`}
        id={outlet.outlet || ``}
        onChange={handleCheck}
        label={
          <React.Fragment>
            <Text key={outlet.bpId} variant="label-100">
              {outlet.outlet}
            </Text>
            {renderFormattedAddress()}
          </React.Fragment>
        }
      />
    );
  };

  const renderOpeningHours = () => {
    let renderOpeningHoursSection: boolean = false;
    outlet.offeredService &&
      outlet.offeredService.length > 0 &&
      outlet.offeredService.forEach((service) => {
        if (service?.openingHours?.length > 0) {
          renderOpeningHoursSection = true;
        }
      });

    return renderOpeningHoursSection;
  };

  const renderWeekDayOpeningHours = (
    weekDay: string,
    openingHours: string[],
  ) => {
    if (openingHours.length === 0) return;

    return (
      <Text variant="caption-200" className={styles.openingHoursDay}>
        {weekDay}
        {openingHours.map((splitHoursMap, index) =>
          index !== openingHours.length - 1
            ? `${splitHoursMap} / `
            : splitHoursMap,
        )}
      </Text>
    );
  };

  const renderWeekDayOpeningHoursMaps = (
    weekDay: string,
    openingHours: string[],
  ) => {
    if (openingHours.length === 0) return;

    return (
      <Text className={outletStyles.openingHoursDay}>
        <span className={outletStyles.openingDay}>{weekDay}</span>
        <span className={outletStyles.openingHours}>
          {openingHours.map((splitHoursMap, index) =>
            index !== openingHours.length - 1
              ? `${splitHoursMap} / `
              : splitHoursMap,
          )}
        </span>
      </Text>
    );
  };

  const findWeekDayAndRenderOpeningHours = (
    day: string,
    offeredService: Services[],
  ) => {
    const currentServiceId = Number(selectedService);
    const dayAndHoursDataForSelectedService = offeredService.find(
      (service) => service.serviceId === currentServiceId,
    );
    const weekDayData = dayAndHoursDataForSelectedService?.openingHours?.filter(
      (data) => data.weekDay === day,
    );

    if (weekDayData) {
      const splitHours = weekDayData.map((weekDayDataMap) =>
        weekDayDataMap.hours.split(`-`),
      );

      const hrs = showMap
        ? ``
        : aemTranslations.outletlocator_result_openingHours_hrs;

      const hours = splitHours.map((splitHoursMap) =>
        splitHoursMap[0] && splitHoursMap[1]
          ? splitHoursMap[0].slice(0, 5) +
            ` -` +
            splitHoursMap[1].slice(0, 6) +
            ` ` +
            hrs
          : ``,
      );

      const weekDay = `${
        dayAEMTranslationsMap[day as keyof {[k in DayType]: string}]
      }: `;

      return showMap
        ? renderWeekDayOpeningHoursMaps(weekDay, hours)
        : renderWeekDayOpeningHours(weekDay, hours);
    }
    return;
  };

  const renderServices = () => {
    const availableServicesIds: String[] = [];
    outlet.offeredService?.forEach((obj) =>
      availableServicesIds.push(String(obj.serviceId)),
    );
    const availableServicesNames: string[] = [];
    servicesNames?.forEach((s: any) => {
      const [serviceValue, serviceLabel] = s?.split(`:`);
      if (availableServicesIds?.includes(serviceValue)) {
        availableServicesNames.push(serviceLabel);
      }
    });
    return (
      <div
        className={
          showMap ? styles.showMapListedServices : styles.listedService
        }
      >
        <ul>
          {availableServicesNames.map((service, index) => {
            return (
              <li key={index}>
                <Text
                  variant={showMap ? `P-100` : `caption-200`}
                  className={showMap ? `` : styles.listedService}
                >
                  {service}
                </Text>
              </li>
            );
          })}
        </ul>
      </div>
    );
  };

  const renderFormattedAddress = () => {
    let formattedAddress: string | any[];

    variantConfig.featureFlags &&
    variantConfig.featureFlags.includes(`crossBorder`)
      ? (formattedAddress = addressFormatter.format(
          {
            houseNumber: outlet.buildingNumber,
            road: outlet.street,
            city: outlet.city,
            postcode: outlet.postalCode,
            countryCode: getCountryCode(marketId),
            country: outlet.country,
          },
          {
            output: `array`,
          },
        ))
      : (formattedAddress = addressFormatter.format(
          {
            houseNumber: outlet.buildingNumber,
            road: outlet.street,
            city: outlet.city,
            postcode: outlet.postalCode,
            countryCode: getCountryCode(marketId),
          },
          {
            output: `array`,
          },
        ));

    return Array.from({length: formattedAddress.length}, (_element, index) => (
      <Text key={index} variant="caption-200">
        {formattedAddress[index]}
      </Text>
    ));
  };
  const renderFormattedAddressWithMaps = () => {
    let formattedAddress: string | any[];

    variantConfig.featureFlags &&
    variantConfig.featureFlags.includes(`crossBorder`)
      ? (formattedAddress = addressFormatter.format(
          {
            houseNumber: outlet.buildingNumber,
            road: outlet.street,
            city: outlet.city,
            postcode: outlet.postalCode,
            countryCode: getCountryCode(marketId),
            country: outlet.country,
          },
          {
            output: `array`,
          },
        ))
      : (formattedAddress = addressFormatter.format(
          {
            houseNumber: outlet.buildingNumber,
            road: outlet.street,
            city: outlet.city,
            postcode: outlet.postalCode,
            countryCode: getCountryCode(marketId),
          },
          {
            output: `array`,
          },
        ));

    return Array.from({length: formattedAddress.length}, (_element, index) => (
      <Text
        key={index}
        variant="paragraph-100"
        className={outletStyles.address}
      >
        {formattedAddress[index]}
      </Text>
    ));
  };

  return (
    <React.Fragment>
      {showMap ? (
        <div
          ref={selectedOrHovered ? selectedItemRef : null}
          className={`${outletStyles.outlet}  ${
            selected ? outletStyles.outletSelected : ``
          } 
          ${hovered ? outletStyles.mapHovered : ``}
          `}
          onClick={(e: React.MouseEvent) => {
            e.preventDefault();
            e.stopPropagation();
            handleCheckAgent(
              selected ? `` : outlet.bpId,
              selected ? `` : outlet.outlet,
            );
          }}
          onMouseEnter={() => {
            handleMouse?.(outlet.bpId, `listHover`);
          }}
          onMouseLeave={() => {
            handleMouse?.(``, `listHover`);
          }}
        >
          {selected ? (
            <div className={outletStyles.outletListSelectArea}>
              <svg
                width="24"
                height="24"
                viewBox="0 0 24 24"
                fill="none"
                xmlns="http://www.w3.org/2000/svg"
              >
                <rect
                  x="0.5"
                  y="0.5"
                  width="23"
                  height="23"
                  rx="11.5"
                  fill="#141413"
                />
                <rect
                  x="0.5"
                  y="0.5"
                  width="23"
                  height="23"
                  rx="11.5"
                  stroke="#6B747B"
                />
                <mask
                  id="mask0_5515_38842"
                  style={{maskType: `alpha`}}
                  maskUnits="userSpaceOnUse"
                  x="6"
                  y="7"
                  width="14"
                  height="10"
                >
                  <path
                    fillRule="evenodd"
                    clipRule="evenodd"
                    d="M19.3536 8.35353L11 16.7071L6.64648 12.3535L7.35359 11.6464L11 15.2929L18.6465 7.64642L19.3536 8.35353Z"
                    fill="#141413"
                  />
                </mask>
                <g mask="url(#mask0_5515_38842)">
                  <rect x="5" y="4" width="16" height="16" fill="white" />
                </g>
              </svg>
            </div>
          ) : (
            <div className={outletStyles.outletListSelectArea}>
              <svg
                width="24"
                height="24"
                viewBox="0 0 24 24"
                fill="none"
                xmlns="http://www.w3.org/2000/svg"
              >
                <rect
                  x="0.5"
                  y="0.5"
                  width="23"
                  height="23"
                  rx="11.5"
                  stroke="#6B747B"
                />
                <text
                  x="50%"
                  y="55%"
                  dominantBaseline="middle"
                  textAnchor="middle"
                  fontSize="14"
                  fill="#141413"
                  id="dynamic-number"
                >
                  {outletIndex}
                </text>
              </svg>
            </div>
          )}
          <div className={outletStyles.outletMainInfo}>
            <div className={outletStyles.outletAddress}>
              <div className={outletStyles.leftContainer}>
                <div>{renderDefaultVariantUIwithMaps()}</div>

                <div className={outletStyles.outletDistance}>
                  <span className={outletStyles.p100}>
                    {getBeautifiedDistance(
                      marketId as MarketId,
                      Number(outlet.distance),
                    )}
                  </span>
                </div>
              </div>
              <div className={outletStyles.showOutletDetails}>
                {expendId === outlet.bpId ? (
                  <span
                    onClick={(e) => {
                      changeExpenedId?.(``);
                      e.stopPropagation();
                    }}
                  >
                    {aemTranslations.outletlocator_result_showLess}
                    <img src={showOutletDetailsSvg} alt="svg  is not found" />
                  </span>
                ) : (
                  <span
                    onClick={(e) => {
                      changeExpenedId?.(outlet.bpId);
                      track(`click`, `more_details`, `feature`, [outlet]);
                      e.stopPropagation();
                    }}
                  >
                    {aemTranslations.outletlocator_result_showMore}
                    <img src={hideOutletDetailsSvg} alt="svg  is not found" />
                  </span>
                )}
              </div>
              {expendId === outlet.bpId && (
                <div>
                  {outlet.offeredService &&
                    outlet.offeredService.length > 0 &&
                    renderOpeningHours() && (
                      <>
                        <Text className={outletStyles.outletOpeningHours}>
                          {aemTranslations.outletlocator_result_openingHours}
                        </Text>
                        <div>
                          {findWeekDayAndRenderOpeningHours(
                            `MO`,
                            outlet.offeredService,
                          )}
                          {findWeekDayAndRenderOpeningHours(
                            `TU`,
                            outlet.offeredService,
                          )}
                          {findWeekDayAndRenderOpeningHours(
                            `WE`,
                            outlet.offeredService,
                          )}
                          {findWeekDayAndRenderOpeningHours(
                            `TH`,
                            outlet.offeredService,
                          )}
                          {findWeekDayAndRenderOpeningHours(
                            `FR`,
                            outlet.offeredService,
                          )}
                          {findWeekDayAndRenderOpeningHours(
                            `SA`,
                            outlet.offeredService,
                          )}
                          {findWeekDayAndRenderOpeningHours(
                            `SU`,
                            outlet.offeredService,
                          )}
                        </div>
                        {selectedService !== ServiceType.TEST_DRIVE &&
                          (outlet.email || outlet.phone) && (
                            <>
                              <Text className={outletStyles.outletOpeningHours}>
                                {aemTranslations.outletlocator_result_contact}
                              </Text>
                              <div className={outletStyles.contactDetails}>
                                {outlet.email && (
                                  <div
                                    className={outletStyles.contactDetails_mail}
                                  >
                                    <div>
                                      <TextLink
                                        className={
                                          outletStyles.textLinkFontStyle
                                        }
                                        icon={{name: `newsletter-mail--small`}}
                                        variant="hyperlink-legal"
                                        linkText={`${outlet.email}`}
                                        aria-label=""
                                        href={`mailto:${outlet.email}`}
                                        onClick={(e) => e.preventDefault()}
                                      />
                                    </div>
                                  </div>
                                )}
                                {outlet.phone && (
                                  <div
                                    className={
                                      outletStyles.contactDetails_phone
                                    }
                                  >
                                    <div>
                                      <TextLink
                                        className={
                                          outletStyles.textLinkFontStyle
                                        }
                                        icon={{name: `call--small`}}
                                        variant="hyperlink-legal"
                                        linkText={`${outlet.phone}`}
                                        href={`tel:${outlet.phone}`}
                                        aria-label="Send email"
                                        onClick={(e) => e.preventDefault()}
                                      />
                                    </div>
                                  </div>
                                )}
                              </div>
                            </>
                          )}
                        {showServicesInOutletResults && (
                          <div>
                            <Text
                              variant="P-100"
                              className={outletStyles.services}
                            >
                              {aemTranslations.outletlocator_result_services}
                            </Text>
                            {renderServices()}
                          </div>
                        )}
                      </>
                    )}
                </div>
              )}
              {selected &&
                variant === `checkout` &&
                aemTranslations?.confirmSelectionButtonText && (
                  <div className={outletStyles.confirmSelection}>
                    <Button
                      variant={`primary`}
                      size={`200`}
                      onClick={(e) => {
                        e.stopPropagation();
                        getSelectedOutlets?.(outlet);
                        track(`click`, `confirm_selection`, `feature`, [
                          outlet,
                        ]);
                      }}
                    >
                      {aemTranslations?.confirmSelectionButtonText}
                    </Button>
                  </div>
                )}
            </div>
          </div>
        </div>
      ) : (
        <div className={styles.outlet}>
          <div className={styles.outletMainInfo}>
            <div className={styles.outletAddress}>
              {hasPrimaryButtonConfigured ||
              hasReturnViaDoneFunctionTrue ||
              true
                ? renderRadioButtonsVariantUI()
                : renderDefaultVariantUI()}
            </div>
            {outlet.distance && (
              <div className={styles.outletDistance}>
                <div className={styles.outletDistanceIcon}>
                  <Icon name={`dealer-locator-location--small`} />
                </div>
                <Text variant="caption-200">
                  {getBeautifiedDistance(
                    marketId as MarketId,
                    Number(outlet.distance),
                  )}
                </Text>
              </div>
            )}
          </div>
          {showMoreButton &&
            ((outlet.offeredService && outlet.offeredService.length > 0) ||
              outlet.email ||
              outlet.phone) && (
              <Button
                variant="hyperlink"
                size="300"
                onClick={() => {
                  toggleMoreButton(false);
                  toggleOutletDetails(true);
                }}
                className={
                  hasPrimaryButtonConfigured || hasReturnViaDoneFunctionTrue
                    ? styles.showMoreButtonRadioButtonsVariant
                    : styles.showMoreButtonDefaultVariant
                }
              >
                {aemTranslations.outletlocator_result_showMore}
              </Button>
            )}
          {showOutletDetails && (
            <div
              className={
                hasPrimaryButtonConfigured || hasReturnViaDoneFunctionTrue
                  ? styles.outletDetailsRadioButtonsVariant
                  : styles.outletDetailsDefaultVariant
              }
            >
              {outlet.offeredService &&
                outlet.offeredService.length > 0 &&
                renderOpeningHours() && (
                  <>
                    <Text variant="label-100">
                      {aemTranslations.outletlocator_result_openingHours}
                    </Text>
                    <div className={styles.openingHours}>
                      {findWeekDayAndRenderOpeningHours(
                        `MO`,
                        outlet.offeredService,
                      )}
                      {findWeekDayAndRenderOpeningHours(
                        `TU`,
                        outlet.offeredService,
                      )}
                      {findWeekDayAndRenderOpeningHours(
                        `WE`,
                        outlet.offeredService,
                      )}
                      {findWeekDayAndRenderOpeningHours(
                        `TH`,
                        outlet.offeredService,
                      )}
                      {findWeekDayAndRenderOpeningHours(
                        `FR`,
                        outlet.offeredService,
                      )}
                      {findWeekDayAndRenderOpeningHours(
                        `SA`,
                        outlet.offeredService,
                      )}
                      {findWeekDayAndRenderOpeningHours(
                        `SU`,
                        outlet.offeredService,
                      )}
                    </div>
                  </>
                )}
              {(outlet.email || outlet.phone) && (
                <div className={styles.contact}>
                  <Text variant="label-100">
                    {aemTranslations.outletlocator_result_contact}
                  </Text>
                  <div className={styles.contactDetails}>
                    {outlet.email && (
                      <div className={styles.contactDetails_mail}>
                        <div className={styles.contactDetails_mail__icon}>
                          <IconLink
                            icon={{name: `newsletter-mail--small`}}
                            variant="button-primary"
                            href={`mailto:${outlet.email}`}
                            aria-label="Send email"
                            size="200"
                          />
                        </div>
                        <Text variant="caption-200">{outlet.email}</Text>
                      </div>
                    )}
                    {outlet.phone && (
                      <div className={styles.contactDetails_phone}>
                        <div className={styles.contactDetails_phone__icon}>
                          <IconLink
                            icon={{name: `phone--small`}}
                            variant="button-primary"
                            href={`tel:${outlet.phone}`}
                            aria-label="Send email"
                            size="200"
                          />
                        </div>
                        <Text variant="caption-200">{outlet.phone}</Text>
                      </div>
                    )}
                  </div>
                </div>
              )}
              {showServicesInOutletResults &&
                outlet.offeredService &&
                outlet.offeredService.length > 0 && (
                  <div className={styles.services}>
                    <Text variant="label-100">
                      {aemTranslations.outletlocator_result_services}
                    </Text>
                    {renderServices()}
                  </div>
                )}
              <Button
                variant="hyperlink"
                size="300"
                onClick={() => {
                  toggleOutletDetails(false);
                  toggleMoreButton(true);
                }}
                className={styles.showLessButton}
              >
                {aemTranslations.outletlocator_result_showLess}
              </Button>
            </div>
          )}
        </div>
      )}
    </React.Fragment>
  );
}

