import {FeatureAppLoader} from '@feature-hub/react';
import {LABELS_FALLBACK} from '@smart/feature-address-validator';
import {useFeatureAppEnv} from '@smart/feature-app';
import {useTranslations} from '@smart/react-utils';
import {
  Heading,
  Loader,
  Notification,
  Select,
  Text,
} from '@smart/web-components';
import classNames from 'classnames';
import React, {useRef, useState} from 'react';
import type {OutletsInfoModel} from '../../../bff/get-outlets/create-outlets-info-model';
import type {Maybe} from '../../../graphql/types';
import {usePrevious} from '../../common/helpers';
import type {
  LocationDetails,
  LocationModel,
  LocationSearchFAConfig,
  LocationSearchPropLabels,
  SelectOptionType,
} from '../../common/types';
import {unSetBpidVariant} from '../../common/types';
import {useAPI} from '../../hooks/use-api';
import {useLocale} from '../../hooks/use-locale';
import useMemoizedFn from '../../hooks/use-memorized-fn';
import {useTracking} from '../../hooks/use-tracking';
import type {ITrackLoad} from '../../hooks/use-tracking-model';
import {getOutletDetails} from '../../utils/get-outlet-details';
import {
  getCurrentLocation,
  parseFallbackLocation,
} from '../../utils/getCurrentLocation';
import type {AwsMapRef} from '../AwsMap/map';
import AwsMap from '../AwsMap/map';
import {LocationSearch} from '../LocationSearch';
import {type Position} from '../LocationSearch/type';
import Outlets from '../Outlets';
import {TestDriveNotification} from '../TestDriveNotification';
import {AppModelContext} from '../app';
import styles from '../app.module.scss';
import {SelectorV2} from '../selector-v2';
import stylesOfOutlets from './outletlocator.module.scss';
import {type HoverRection, type PaginationData, ServiceType} from './type';

// eslint-disable-next-line complexity
export default function OutletLocator(): JSX.Element {
  /* START OF OUTLET LOCATOR FA CONFIG */
  const apiFetch = useAPI();
  const {
    config: {getSelectedOutlets, showMap = false, variant},
  } = useFeatureAppEnv() as {
    config: {
      getSelectedOutlets: (item: OutletsInfoModel | undefined) => void;
      showMap: boolean;
      variant: string;
    };
  };

  const mapWrapRef = useRef<HTMLDivElement | null>(null);
  const [addressForOutletsAPI, setAddress] = useState<LocationModel>();
  const [foundOutlets, setFoundOutlets] = useState<
    OutletsInfoModel[] | undefined
  >([]);
  const [isOutZoom, setOutZoom] = useState<boolean>(false);
  const [expendId, setExpendId] = useState<string>();
  const outletsRef = useRef<{
    getSelectedOutletBpId: (outletId: string, outletName: string) => void;
    changeExpenedId: (outletId: string) => void;
  }>(null);
  const mapRef = useRef<AwsMapRef>(null);
  const [selectId, setSelectId] = useState<string | null>(null);
  const [hover, setHover] = useState<HoverRection>();
  const [showSearchLoader, setSearchLoader] = useState<boolean>(false);
  const [servicesOptions, setServicesOptions] = useState<SelectOptionType[]>(
    [],
  );
  const [showServiceDropdown, setShowServiceDropdown] =
    useState<boolean>(false);
  const [showSearch, setShowSearch] = useState<boolean>(false);
  const [selectedService, setSelectedService] = useState<string>(``);
  const [serverError, setServerError] = useState<string>();
  const [configError, setConfigError] = useState<boolean>(false);
  const [location, setLocation] = useState<Position>();
  const [track] = useTracking<ITrackLoad>();
  const {'pub-sub': pubSubService, 'endpoint-directory': endpointDirectory} =
    useFeatureAppEnv().featureServices;
  const baseUrl = useFeatureAppEnv().baseUrl;
  const aemTranslations =
    React.useContext(AppModelContext).outletLocatorFeatureAppUi || {};
  const servicesNames = aemTranslations.serviceNames;
  const locationSearchFAHash =
    React.useContext(AppModelContext).locationSearchFAVersion || {};
  const variantConfig =
    React.useContext(AppModelContext).outletLocatorVariant || {};
  const {marketId} = useLocale();
  const outletLocatorTranslation =
    React.useContext(AppModelContext).outletLocatorTranslation || {};
  const {t} = useTranslations(outletLocatorTranslation?.LatitudeAndlLongitude);
  const {latitude: defaultLatitude, longitude: defaultLongitude} =
    parseFallbackLocation(t(marketId));
  const [defaultSeletcOutlet, setDefaultSeletcOutlet] =
    useState<OutletsInfoModel>();

  const enabledServicesForTheVariant = variantConfig.enabledServicesForVariant;

  const crossCountrySearch =
    (variantConfig.featureFlags &&
      variantConfig.featureFlags.includes(`crossBorder`)) ||
    (selectedService === ServiceType.MAINTENANCE && showMap)
      ? `on`
      : `off`;

  const [modelType, setModelType] = useState<string | undefined>(``);

  const params = new URLSearchParams(document.location.search);
  const bpid = params.get(`bpid`) || ``;

  const availableServicesForTheVariant: SelectOptionType[] = [];
  const [paginationData, setPaginationData] = useState<PaginationData>({
    currentPage: 1,
    pageSize: 5,
    hasNextPage: false,
  });

  const changeExpenedId = (id: string) => {
    setExpendId(id);
  };

  const handleMouse = (cbpid: string, type: `mapHover` | `listHover`) => {
    setHover({bpid: cbpid, type});
  };

  const handlePagination = async (currentPage: number, pageSize: number) => {
    setSearchLoader(true);
    const {outlets, hasNextPage} = await apiFetch(
      addressForOutletsAPI as LocationModel,
      crossCountrySearch,
      selectedService,
      showMap,
      {
        currentPage,
        pageSize,
      },
    );

    const outletsLatest = [...(foundOutlets || []), ...outlets];

    if (bpid) {
      const hasDefaultOutlet = outlets.find(
        (o) => o.bpId === defaultSeletcOutlet?.bpId,
      );
      if (!hasDefaultOutlet && defaultSeletcOutlet) {
        setFoundOutlets(
          outletsLatest.sort(
            (a, b) => Number(a?.distance || 0) - Number(b?.distance || 0),
          ),
        );
      } else {
        const uniqueOutlets = Array.from(
          new Map(outletsLatest.map((item) => [item.bpId, item])).values(),
        ).sort((a, b) => Number(a?.distance || 0) - Number(b?.distance || 0));

        setFoundOutlets(uniqueOutlets);
      }
    } else {
      setFoundOutlets(outletsLatest);
    }

    setPaginationData({currentPage, pageSize, hasNextPage});
    setSearchLoader(false);
  };

  React.useEffect(() => {
    return pubSubService.subscribe(
      `test-drive-model-update`,
      (type?: string) => {
        setModelType(type);
        if (outletsRef.current)
          outletsRef.current.getSelectedOutletBpId(``, ``);
        setSelectId(``);
      },
    );
  }, [pubSubService]);

  React.useEffect(() => {
    track(`click`, `outlet.load`, `impression`);
  }, []);

  React.useEffect(() => {
    if (
      foundOutlets &&
      foundOutlets.length > 0 &&
      getSelectedOutlets &&
      !unSetBpidVariant.includes(variant)
    ) {
      const outlet = foundOutlets.find(
        (item: OutletsInfoModel) => item.bpId === selectId,
      );

      outlet && getSelectedOutlets({...outlet, modelType});
    }
  }, [selectId]);

  React.useEffect(() => {
    if (variantConfig) {
      // Based on AEM Variant Config we show / dont show the service selection dropdown
      variantConfig.featureFlags &&
        setShowServiceDropdown(
          variantConfig.featureFlags.includes(`serviceSelectionDropdown`),
        );

      // If we dont show the dropdown, we take first available service from CF and search based on that
      // To be changed once API is enhanced to search with multiple services
      if (
        (!variantConfig.featureFlags ||
          !variantConfig.featureFlags.includes(`serviceSelectionDropdown`)) &&
        variantConfig.enabledServicesForVariant
      ) {
        const individualServiceForVariant =
          variantConfig.enabledServicesForVariant[0] || ``;
        setSelectedService(individualServiceForVariant);
      }

      // To be removed once API is enhanced to search with multiple services
      const amountOfEnabledServices =
        variantConfig.enabledServicesForVariant?.length || [];
      if (
        Number(amountOfEnabledServices) > 1 &&
        (!variantConfig.featureFlags ||
          !variantConfig.featureFlags.includes(`serviceSelectionDropdown`))
      ) {
        setConfigError(true);
      }
    }
  }, [variantConfig]);

  // Based on specified service names translations and specified services for the variant, we create service options in the dropdown list
  React.useEffect(() => {
    servicesNames?.map((s: any) => {
      const [serviceValue, serviceLabel] = s?.split(`:`);
      if (enabledServicesForTheVariant?.includes(serviceValue)) {
        availableServicesForTheVariant.push({
          value: serviceValue,
          label: serviceLabel,
        });
      }
    });
    const defaultOption = !showMap ? [{label: ``, value: ``}] : [];

    const options = defaultOption.concat(
      availableServicesForTheVariant.filter(
        (obj, index, self) =>
          index === self.findIndex((o) => o.value === obj.value),
      ),
    );

    setServicesOptions(options);

    if (variant === `testdrive`) {
      setSelectedService(ServiceType.TEST_DRIVE);
    } else if (showMap && options.length) {
      setSelectedService(options?.[0]?.value || ``);
    }
  }, [servicesNames, variant]);

  // We show the search bar (location search FA) if 1.a service dropdown is enabled + service is picked 2.service dropdown is disabled and user can immediately search
  React.useEffect(() => {
    const showSearchBar =
      (showServiceDropdown && selectedService) || !showServiceDropdown
        ? true
        : false;

    setShowSearch(showSearchBar);
  }, [showServiceDropdown, selectedService]);

  const prevSelectedService = usePrevious(selectedService);

  // If the variant displays service dropdown selection and once user had searched for outlets and then decided to change service, we call the api again and display outlets with newly selected service
  React.useEffect(() => {
    if (showServiceDropdown && foundOutlets && !selectedService) {
      setFoundOutlets(undefined);
    } else if (
      showServiceDropdown &&
      foundOutlets &&
      selectedService !== prevSelectedService
    ) {
      const fetchData = async () => {
        try {
          setFoundOutlets(undefined);
          setSearchLoader(true);
          const {outlets, hasNextPage} = await apiFetch(
            addressForOutletsAPI as LocationModel,
            crossCountrySearch,
            selectedService,
            showMap,
            {
              currentPage: 1,
              pageSize: 5,
            },
          );
          setPaginationData({
            currentPage: 1,
            pageSize: 5,
            hasNextPage: showMap ? hasNextPage : false,
          });
          setFoundOutlets(outlets);
          setServerError(undefined);
        } catch (error) {
          console.error;
          setServerError(error as string);
        } finally {
          setSearchLoader(false);
        }
      };
      // eslint-disable-next-line  @typescript-eslint/no-floating-promises
      addressForOutletsAPI && fetchData();
    }
  }, [selectedService, foundOutlets, showServiceDropdown]);

  const changeCurrentLocation = async (): Promise<{
    lat: number;
    lng: number;
    outlet?: OutletsInfoModel;
  }> => {
    const {latitude = defaultLatitude, longitude = defaultLongitude} =
      await getCurrentLocation();
    mapRef.current?.handleMapLoaded(false);
    const adress = {
      lat: latitude,
      long: longitude,
      postalCode: `00000`,
      searchTerm: ``,
    };

    if (bpid) {
      const outletDetails = await getOutletDetails(
        baseUrl,
        endpointDirectory,
        {
          lat: latitude,
          long: longitude,
        },
        bpid,
      );

      setDefaultSeletcOutlet(outletDetails);

      setAddress(adress);

      setLocation({lat: latitude, lng: longitude});
      return {lat: latitude, lng: longitude, outlet: outletDetails};
    }

    setAddress(adress);
    setLocation({lat: latitude, lng: longitude});
    return {lat: latitude, lng: longitude};
  };

  React.useEffect(() => {
    let isSubscribed = true;

    const initializeLocation = async () => {
      if (!addressForOutletsAPI && showMap && !showSearch) {
        const {outlet} = await changeCurrentLocation();

        if (bpid) {
          setSelectId(bpid);
          setExpendId(bpid);
          outlet && getSelectedOutlets({modelType, ...outlet});
        }
      }
    };

    // eslint-disable-next-line @typescript-eslint/no-floating-promises
    initializeLocation();

    const fetchData = async () => {
      if (!addressForOutletsAPI) return;
      try {
        setFoundOutlets(undefined);
        setSearchLoader(true);
        const {outlets, hasNextPage} = await apiFetch(
          addressForOutletsAPI as LocationModel,
          crossCountrySearch,
          selectedService,
          showMap,
          {
            currentPage: 1,
            pageSize: 5,
          },
        );
        setPaginationData({
          currentPage: 1,
          pageSize: 5,
          hasNextPage: showMap ? hasNextPage : false,
        });
        if (isSubscribed) {
          if (bpid) {
            const hasDefaultOutlet = outlets.find(
              (o) => o.bpId === defaultSeletcOutlet?.bpId,
            );
            if (!hasDefaultOutlet && defaultSeletcOutlet) {
              const outletsLatest = [...outlets, defaultSeletcOutlet];
              setFoundOutlets(outletsLatest);
            } else {
              setFoundOutlets(outlets);
            }
          } else {
            setFoundOutlets(outlets);
          }

          setServerError(undefined);
        }
      } catch (error) {
        console.error;
        setServerError(error as string);
      } finally {
        setSearchLoader(false);
        mapRef.current?.handleSearchAreaVisible(false);
      }
    };
    // eslint-disable-next-line  @typescript-eslint/no-floating-promises
    addressForOutletsAPI && fetchData();

    return () => {
      isSubscribed = false;
    };
  }, [addressForOutletsAPI]);
  /* END OF OUTLET LOCATOR FA CONFIG */

  /* START OF Location Search FA CONFIG */
  const locationSearchConfig = {
    minCharsToSearch: 2,
    enhancedFunctionality: showMap,
    selectedService,
  };

  const getCompleteAddress = (
    address?: LocationDetails,
    searchedInput?: string,
  ) => {
    if (showMap && mapRef.current) mapRef.current.handleMapLoaded(false);

    const postalCode = address?.address?.postalCode || `00000`;
    const lat = address?.position?.lat;
    const long = address?.position?.lng;
    const searchTerm = searchedInput;
    if (postalCode && lat && long && searchTerm) {
      setAddress({postalCode, lat, long, searchTerm});
    }
  };
  const hintMessage: Maybe<string> | undefined =
    aemTranslations.address_validator_hint_message;
  const hintMessageAmount = hintMessage?.replace(
    `{{amount}}`,
    `${locationSearchConfig.minCharsToSearch}`,
  );

  const locationSearchFAConfig: LocationSearchFAConfig = {
    onComplete: getCompleteAddress,
    getCurrentLocation,
    configs: locationSearchConfig,
    labels: {
      ...LABELS_FALLBACK,
      hintMessage: hintMessageAmount,
      input: aemTranslations.address_validator_input,
      errorMessageMinLength: hintMessageAmount,
    } as LocationSearchPropLabels,
    crossCountrySearch,
  };

  const handleMarkerClick = useMemoizedFn((coords: OutletsInfoModel) => {
    if (outletsRef.current) {
      const isChangeSelect = selectId === coords.bpId;

      setSelectId(!isChangeSelect ? coords.bpId : ``);

      outletsRef.current.getSelectedOutletBpId(
        !isChangeSelect ? coords.bpId : ``,
        !isChangeSelect ? coords.outlet || `` : ``,
      );

      if (unSetBpidVariant.includes(variant) || !coords.bpId) return;

      const url = new URL(window.location.href);

      if (url.searchParams.get(`bpid`) !== coords.bpId) {
        url.searchParams.set(`bpid`, coords.bpId);
      } else {
        url.searchParams.delete(`bpid`);
      }

      window.history.pushState({}, ``, url.toString());
    }
  });

  const locationSearchBaseUrl =
    `/__app__/location-search-app/` + locationSearchFAHash.versionHash;

  const onMapDrag = (position: {lat: number; lng: number}) => {
    const adress = {
      lat: position.lat,
      long: position.lng,
      postalCode: `00000`,
      searchTerm: ``,
    };
    setAddress(adress);
  };

  /* END OF Location Search FA CONFIG */
  const mapStyle = isOutZoom
    ? stylesOfOutlets.mapWrapperOutZoom
    : stylesOfOutlets.mapWrapper;
  return (
    <div className={showMap ? styles.mapOutletLocator : styles.outletLocator}>
      {configError && (
        <Notification
          text={`CF configuration error - Multiple services were selected, while feature toggle to show service selection is not selected`}
          variant="error"
          className={styles.configError}
        />
      )}
      {!showMap && (
        <Heading
          variant="headline-functional-200"
          className={styles.outletLocatorTitle}
        >
          {aemTranslations.outletlocator_title}
        </Heading>
      )}
      <React.Fragment>
        {showServiceDropdown && !showMap && (
          <>
            <Text
              variant="paragraph-100"
              className={styles.outletLocatorSubtitle}
            >
              {aemTranslations.outletlocator_servicesInstructions}
            </Text>
            <div className={styles.selectService}>
              <Select
                id="select-service"
                value={selectedService}
                label={
                  aemTranslations.outletlocator_servicesDropdownSelection ||
                  `Selected outlet type`
                }
                name="select-service"
                onChange={(event) => {
                  setSelectedService(event.target.value);
                }}
                options={servicesOptions}
              />
            </div>
          </>
        )}
      </React.Fragment>
      {showMap ? (
        <React.Fragment>
          <div className={mapStyle} ref={mapWrapRef}>
            <AwsMap
              locations={foundOutlets}
              onMarkerClick={handleMarkerClick}
              setOutZoom={setOutZoom}
              isOutZoom={isOutZoom}
              selectId={selectId}
              hover={hover}
              changeExpenedId={changeExpenedId}
              location={location}
              onMapDrag={onMapDrag}
              ref={mapRef}
            />

            <div className={stylesOfOutlets.outletsList}>
              <LocationSearch
                getCompleteAddress={getCompleteAddress}
                placeholder={aemTranslations?.address_validator_input ?? ``}
                changeCurrentLocation={changeCurrentLocation}
                crossCountrySearch={crossCountrySearch}
              />
              <React.Fragment>
                {showServiceDropdown && showMap && (
                  <div>
                    <SelectorV2
                      onClick={(item) => {
                        setSelectedService(item?.value);
                      }}
                      servicesOptions={servicesOptions}
                      selectedService={selectedService}
                    />
                  </div>
                )}
              </React.Fragment>

              {showMap &&
                variant !== `testdrive` &&
                selectedService === ServiceType.TEST_DRIVE && (
                  <TestDriveNotification />
                )}

              {foundOutlets && (
                <Outlets
                  onMarkerClick={handleMarkerClick}
                  outlets={foundOutlets}
                  foundOutletsSourceLength={foundOutlets?.length ?? 0}
                  searchTerm={addressForOutletsAPI?.searchTerm}
                  selectedService={selectedService}
                  ref={outletsRef}
                  handleMouse={handleMouse}
                  hover={hover}
                  changeExpenedId={changeExpenedId}
                  expendId={expendId}
                  handlePagination={handlePagination}
                  paginationData={paginationData}
                  showSearchLoader={showSearchLoader}
                />
              )}

              {showSearchLoader && (
                <div
                  className={classNames(styles.loaderWrapper, {
                    [`${styles.showSerachLoader}`]:
                      !foundOutlets || !foundOutlets?.length,
                  })}
                >
                  <Loader
                    messageId="outlet-locator-list-loading"
                    size="medium"
                  />
                </div>
              )}
            </div>
          </div>
        </React.Fragment>
      ) : (
        <React.Fragment>
          {showSearch && (
            <FeatureAppLoader
              featureAppId="location-search"
              baseUrl={locationSearchBaseUrl}
              src="/assets/feature-app/feature-app.js"
              config={locationSearchFAConfig}
            />
          )}
          {serverError && (
            <Notification
              closeButton={{
                ariaLabel: `Close`,
                onClick: () => setServerError(undefined),
              }}
              text={aemTranslations.outletlocator_error || `Server error`}
              variant="error"
              className={styles.serverError}
            />
          )}
          {foundOutlets && (
            <Outlets
              foundOutletsSourceLength={foundOutlets?.length ?? 0}
              outlets={foundOutlets}
              searchTerm={addressForOutletsAPI?.searchTerm}
              selectedService={selectedService}
            />
          )}
          {showSearchLoader && (
            <div className={styles.loader}>
              <Loader messageId="outlet-locator-loading" size="medium" />
            </div>
          )}
        </React.Fragment>
      )}
    </div>
  );
}

