import type {OutletsInfoModel} from '../../../bff/get-outlets/create-outlets-info-model';

export type HoverRection = {
  bpid: string;
  type: `mapHover` | `listHover`;
};

export type PaginationData = {
  currentPage: number;
  pageSize: number;
  hasNextPage?: boolean;
};

export enum ServiceType {
  NEW_CAR_SALES = `1`,
  USED_CAR_SALES = `2`,
  TRADE_IN = `3`,
  TEST_DRIVE = `4`,
  MAINTENANCE = `5`,
  REPAIR = `6`,
  WARRANTY = `7`,
  BODY_PAINT = `8`,
  BREAKDOWN = `9`,
  TIRE_CHANGE = `10`,
  RECALL = `11`,
  KEY_THROWER = `12`,
  ACTIVE_RECEPTION = `13`,
  PICKUP_DELIVERY = `14`,
  KEY_LOCKER = `15`,
}

export interface AwsMapProps {
  locations?: OutletsInfoModel[] | undefined;
  onMarkerClick?: (coords: OutletsInfoModel) => void;
  changeExpenedId?: (bpid: string) => void;
  onMapDrag?: (position: {lat: number; lng: number}) => void;
  isOutZoom?: boolean;
  setOutZoom?: (outZoom: boolean) => void;
  selectId?: string | null;
  hover?: {
    bpid: string;
    type: `mapHover` | `listHover`;
  };
  location?: {
    lat?: number;
    lng?: number;
  };
}

export interface Feature {
  type: 'Feature';
  geometry: {
    type: 'Point';
    coordinates: [number, number];
  };
  properties: {
    id: string;
    index: number;
    hovered?: boolean;
    selected?: boolean;
  };
}

import {useFeatureAppEnv} from '@smart/feature-app';
import {Button, Text} from '@smart/web-components';
import React, {
  forwardRef,
  useEffect,
  useImperativeHandle,
  useRef,
  useState,
} from 'react';
import type {OutletsInfoModel} from '../../bff/get-outlets/create-outlets-info-model';
import type {Maybe} from '../../graphql/types';
import {useTracking} from '../hooks/use-tracking';
import type {
  ITrackSaveOutlet,
  ITrackSearchResults,
} from '../hooks/use-tracking-model';
import Outlet from './Outlet/Outlet';
import type {PaginationData} from './OutletLocator/type';
import {AppModelContext} from './app';
import styles from './app.module.scss';

interface IProps {
  outlets: OutletsInfoModel[];
  searchTerm?: string;
  selectedService: string;
  onMarkerClick?: (coords: OutletsInfoModel) => void;
  foundOutletsSourceLength: number;
  handleMouse?: (bpid: string, type: `mapHover` | `listHover`) => void;
  hover?: {
    bpid: string;
    type: `mapHover` | `listHover`;
  };
  changeExpenedId?: (outletId: string) => void;
  expendId?: string;
  handlePagination?: (currentPage: number, pageSize: number) => void;
  paginationData?: PaginationData;
  showSearchLoader?: boolean;
}

function Outlets(
  {
    outlets,
    searchTerm,
    selectedService,
    onMarkerClick,
    handleMouse,
    hover,
    changeExpenedId,
    expendId,
    handlePagination,
    paginationData,
    showSearchLoader,
  }: IProps,
  ref: React.Ref<{
    getSelectedOutletBpId: (outletId: string, outletName: string) => void;
    hoverId?: string;
  }>,
): JSX.Element {
  const [selectedOutletBpID, setSelectedOutletBpID] = useState<string>();
  const [selectedOutletName, setSelectedOutletName] = useState<string>();
  const [track] = useTracking<ITrackSaveOutlet | ITrackSearchResults>();
  const outletResultsNum = outlets.length.toString();
  const history = useFeatureAppEnv().featureServices[`s2:history`];
  const {done, config} = useFeatureAppEnv();
  const {showMap} = config as {showMap: boolean};
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    track(
      `click`,
      `outlet.search_results`,
      `search`,
      outlets,
      outletResultsNum,
      searchTerm,
    );
  }, [outlets]);

  useEffect(() => {
    const params = new URLSearchParams(document.location.search);
    const bpid = params.get(`bpid`);
    bpid && setSelectedOutletBpID(bpid);
  }, []);

  const aemTranslations =
    React.useContext(AppModelContext).outletLocatorFeatureAppUi || {};

  const variantConfig =
    React.useContext(AppModelContext).outletLocatorVariant || {};

  const getSelectedOutletBpId = (outletId: string, outletName: string) => {
    setSelectedOutletBpID(outletId);
    setSelectedOutletName(outletName);
  };

  const redirectToNextPage = (
    event: React.MouseEvent<HTMLButtonElement, MouseEvent>,
  ) => {
    if (variantConfig.returnViaDoneFunction && selectedOutletBpID) {
      const outletData = outlets.find(
        (outlet) => outlet.bpId === selectedOutletBpID,
      );
      const data = {
        filterID: selectedService,
        outletData,
      };

      if (done && data) {
        done(data);
      }
    } else if (!variantConfig.returnViaDoneFunction) {
      forwardToNextPage(event);
    }
  };

  const forwardToNextPage = (
    event: React.MouseEvent<HTMLButtonElement, MouseEvent>,
  ) => {
    if (
      selectedOutletBpID &&
      !event.altKey &&
      !event.ctrlKey &&
      !event.metaKey &&
      !event.shiftKey
    ) {
      event.preventDefault();
      track(`click`, `select`, `feature`, [
        {bpId: selectedOutletBpID, outlet: selectedOutletName},
      ]);
      const nextPagePath =
        variantConfig.primaryButtonPage?._path +
        `?selectedoutlet=` +
        selectedOutletBpID;
      history.rootHistory.push({pathname: nextPagePath});
    }
  };

  const navigateToPreviousPage = (
    event: React.MouseEvent<HTMLButtonElement, MouseEvent>,
  ) => {
    if (
      selectedOutletBpID &&
      !event.altKey &&
      !event.ctrlKey &&
      !event.metaKey &&
      !event.shiftKey
    ) {
      event.preventDefault();
      const previousPagePath = variantConfig.secondaryButtonPage?._path || ``;
      history.rootHistory.push({pathname: previousPagePath});
    }
  };

  const renderTopMatchingOutlets = () => {
    if (outlets.length > 0) {
      const resultsMatching: Maybe<string> | undefined =
        aemTranslations.outletlocator_results_matching;
      const topOutlets = resultsMatching?.replace(
        `{{count}}`,
        `${outlets.length}`,
      );
      return <Text>{topOutlets}</Text>;
    }
    return;
  };

  useImperativeHandle(ref, () => ({
    getSelectedOutletBpId,
  }));

  const renderButtons = () => {
    return (
      <React.Fragment>
        {((variantConfig.primaryButtonLabel &&
          variantConfig.primaryButtonPage) ||
          (variantConfig.primaryButtonLabel &&
            variantConfig.returnViaDoneFunction)) && (
          <Button
            variant="primary"
            onClick={(event) => redirectToNextPage(event)}
          >
            {variantConfig.primaryButtonLabel}
          </Button>
        )}
        {variantConfig.secondaryButtonLabel &&
          variantConfig.secondaryButtonPage && (
            <Button
              variant="hyperlink"
              onClick={(event) => navigateToPreviousPage(event)}
            >
              {variantConfig.secondaryButtonLabel}
            </Button>
          )}
      </React.Fragment>
    );
  };

  const handleScroll = () => {
    const container = containerRef.current;
    if (
      container &&
      container.scrollTop + container.clientHeight >=
        container.scrollHeight - 10 &&
      !showSearchLoader &&
      paginationData?.hasNextPage
    ) {
      handlePagination?.(
        (paginationData?.currentPage ?? 0) + 1,
        paginationData?.pageSize ?? 5,
      );
    }
  };

  useEffect(() => {
    const container = containerRef.current;
    if (container) container.addEventListener(`scroll`, handleScroll);

    return () => {
      if (container) container.removeEventListener(`scroll`, handleScroll);
    };
  }, [showSearchLoader]);

  return (
    <div className={showMap ? styles.outletsWapper : styles.outlets}>
      {showMap ? null : renderTopMatchingOutlets()}
      <div
        className={showMap ? styles.listWrap : styles.radio}
        ref={containerRef}
      >
        {outlets &&
          outlets.map((outlet, index) => {
            return (
              <Outlet
                onMarkerClick={onMarkerClick}
                selected={outlet.bpId === selectedOutletBpID}
                key={outlet.bpId}
                outlet={outlet}
                selectedService={selectedService}
                getSelectedOutletBpId={getSelectedOutletBpId}
                outletIndex={index + 1}
                expendId={expendId}
                changeExpenedId={changeExpenedId}
                handleMouse={handleMouse}
                hover={hover}
                redirectToNextPage={redirectToNextPage}
              />
            );
          })}
      </div>
      {!showMap && (
        <div className={styles.checkoutButtons}>
          {outlets.length > 0 && renderButtons()}
        </div>
      )}
      {aemTranslations?.loadMoreButtonText && outlets?.length > 0 && (
        <Button
          variant="secondary"
          onClick={() =>
            handlePagination?.(
              (paginationData?.currentPage ?? 0) + 1,
              paginationData?.pageSize ?? 5,
            )
          }
          className={styles.loadMoreButton}
          loading={{
            isLoading: !!showSearchLoader,
            messageId: `outlet-locator-loading`,
          }}
          disabled={!paginationData?.hasNextPage}
        >
          {aemTranslations?.loadMoreButtonText}
        </Button>
      )}
    </div>
  );
}
export default forwardRef(Outlets);

